const vertex = `#version 300 es
in vec2 a_pos;
void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }
`;

function compile(gl: WebGL2RenderingContext, type: number, source: string) {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    console.warn("[shader-canvas] shader compile failed:", gl.getShaderInfoLog(shader));
    gl.deleteShader(shader);
    return null;
  }
  return shader;
}

/** Builds a program that draws one fragment shader over a fullscreen triangle. */
export function createFullscreenProgram(gl: WebGL2RenderingContext, fragment: string, uniformNames: string[]) {
  const vs = compile(gl, gl.VERTEX_SHADER, vertex);
  const fs = compile(gl, gl.FRAGMENT_SHADER, fragment);
  if (!vs || !fs) {
    gl.deleteShader(vs);
    gl.deleteShader(fs);
    return null;
  }

  const program = gl.createProgram();
  gl.attachShader(program, vs);
  gl.attachShader(program, fs);
  gl.linkProgram(program);
  gl.deleteShader(vs);
  gl.deleteShader(fs);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    console.warn("[shader-canvas] program link failed:", gl.getProgramInfoLog(program));
    gl.deleteProgram(program);
    return null;
  }

  const buffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  const location = gl.getAttribLocation(program, "a_pos");
  gl.enableVertexAttribArray(location);
  gl.vertexAttribPointer(location, 2, gl.FLOAT, false, 0, 0);
  gl.useProgram(program);

  const uniforms: Record<string, WebGLUniformLocation | null> = Object.fromEntries(
    uniformNames.map((name) => [name, gl.getUniformLocation(program, name)]),
  );

  return { program, buffer, uniforms };
}

"use client";

import { useEffect, useRef } from "react";
import { cn } from "@/lib/utils";
import { mountEmberGlow } from "./ember-runtime";

export type EmberGlowProps = {
  color?: string;
  intensity?: number;
  still?: boolean;
  speed?: number;
  interactive?: boolean;
  className?: string;
};

export function EmberGlow({ color = "var(--primary, #ff5a1f)", intensity = 1, still = false,
  speed = 1, interactive = true, className }: EmberGlowProps) {
  const canvas = useRef<HTMLCanvasElement>(null);
  const glow = useRef<ReturnType<typeof mountEmberGlow>>(undefined);
  useEffect(() => {
    if (!canvas.current) return;
    glow.current = mountEmberGlow(canvas.current);
    return () => { glow.current?.dispose(); glow.current = undefined; };
  }, []);
  useEffect(() => {
    glow.current?.update({ intensity: Math.max(0, intensity), still, speed, interactive });
  }, [intensity, still, speed, interactive, color]);
  return <canvas ref={canvas} aria-hidden="true" style={{ color }}
    className={cn("pointer-events-none block size-full", className)} />;
}

import { createFullscreenProgram } from "./ember-glow-gl";
import { emberShader, uniforms } from "./ember-shader";

export function createEmberRenderer(canvas: HTMLCanvasElement) {
  const gl = canvas.getContext("webgl2", { alpha: true, premultipliedAlpha: true, antialias: false });
  if (!gl) return;
  const setup = createFullscreenProgram(gl, emberShader, uniforms);
  if (!setup) return;
  const u = setup.uniforms;
  const pixel = document.createElement("canvas");
  pixel.width = pixel.height = 1;
  const palette = pixel.getContext("2d", { willReadFrequently: true });
  let lastColor = "";
  let lastScheme = "";

  return {
    resize() {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const width = Math.max(1, Math.round(canvas.clientWidth * dpr));
      const height = Math.max(1, Math.round(canvas.clientHeight * dpr));
      if (canvas.width !== width) canvas.width = width;
      if (canvas.height !== height) canvas.height = height;
      gl.viewport(0, 0, width, height);
      gl.uniform2f(u.u_res, width, height);
    },
    refreshPalette() {
      const { color, colorScheme } = getComputedStyle(canvas);
      if (color === lastColor && colorScheme === lastScheme) return false;
      lastColor = color;
      lastScheme = colorScheme;
      gl.uniform1f(u.u_dark, Number(colorScheme === "dark"));
      if (palette) {
        palette.clearRect(0, 0, 1, 1);
        palette.fillStyle = color;
        palette.fillRect(0, 0, 1, 1);
        const [r, g, b] = palette.getImageData(0, 0, 1, 1).data;
        gl.uniform3f(u.u_accent, r / 255, g / 255, b / 255);
      }
      return true;
    },
    draw(time: number, intensity: number, x: number, y: number) {
      gl.uniform1f(u.u_time, time);
      gl.uniform1f(u.u_intensity, intensity);
      gl.uniform2f(u.u_mouse, x * canvas.width, y * canvas.height);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    },
    dispose() {
      gl.deleteBuffer(setup.buffer);
      gl.deleteProgram(setup.program);
    },
  };
}

import { createEmberRenderer } from "./ember-renderer";

type Options = { intensity: number; still: boolean; speed: number; interactive: boolean };

export function mountEmberGlow(canvas: HTMLCanvasElement) {
  const host = canvas.parentElement;
  if (!host) return;
  let renderer = createEmberRenderer(canvas);
  const reduced = matchMedia("(prefers-reduced-motion: reduce)");
  const theme = matchMedia("(prefers-color-scheme: dark)");
  let options: Options;
  let inView = false;
  let frame = 0;
  let last = 0;
  let time = 6;
  // Normalized coordinates keep the frozen pointer influence stable on resize.
  const pointer = { x: 0.5, y: 0.5, targetX: 0.5, targetY: 0.5 };
  const frozen = () => options.still || reduced.matches;
  const visible = () => inView && !document.hidden;
  const stop = () => { cancelAnimationFrame(frame); frame = 0; };
  const draw = () => renderer?.draw(time, options.intensity, pointer.x, pointer.y);
  const tick = (now: number) => {
    time += Math.min(50, now - last) * options.speed / 1000;
    last = now;
    pointer.x += (pointer.targetX - pointer.x) * 0.12;
    pointer.y += (pointer.targetY - pointer.y) * 0.12;
    draw();
    frame = requestAnimationFrame(tick);
  };
  const refresh = () => {
    stop();
    if (!renderer || !options || !visible()) return;
    renderer.resize();
    renderer.refreshPalette();
    draw();
    if (!frozen()) {
      last = performance.now();
      frame = requestAnimationFrame(tick);
    }
  };
  const paletteChanged = () => {
    if (options && visible() && renderer?.refreshPalette() && frozen()) draw();
  };
  const leave = () => { pointer.targetX = pointer.targetY = 0.5; };
  const move = (event: PointerEvent) => {
    if (!options?.interactive || frozen() || !visible() || event.pointerType === "touch") return;
    const box = canvas.getBoundingClientRect();
    if (!box.width || !box.height || event.clientX < box.left || event.clientX > box.right ||
        event.clientY < box.top || event.clientY > box.bottom) { leave(); return; }
    pointer.targetX = (event.clientX - box.left) / box.width;
    pointer.targetY = 1 - (event.clientY - box.top) / box.height;
  };
  const lost = (event: Event) => { event.preventDefault(); stop(); renderer = undefined; };
  const restored = () => { renderer = createEmberRenderer(canvas); refresh(); };
  const viewer = new IntersectionObserver(([entry]) => { inView = entry.isIntersecting; refresh(); });
  viewer.observe(canvas);
  const resize = new ResizeObserver(refresh);
  resize.observe(canvas);
  const colors = new MutationObserver(paletteChanged);
  for (let node: HTMLElement | null = canvas; node; node = node.parentElement) {
    colors.observe(node, { attributes: true, attributeFilter: ["class", "style", "data-theme"] });
  }
  host.addEventListener("pointermove", move, { passive: true });
  host.addEventListener("pointerleave", leave);
  document.addEventListener("visibilitychange", refresh);
  reduced.addEventListener("change", refresh);
  theme.addEventListener("change", paletteChanged);
  window.addEventListener("resize", refresh);
  canvas.addEventListener("webglcontextlost", lost);
  canvas.addEventListener("webglcontextrestored", restored);
  return {
    update(next: Options) {
      options = next;
      if (!next.interactive) { leave(); pointer.x = pointer.y = 0.5; }
      refresh();
    },
    dispose() {
      stop();
      viewer.disconnect();
      resize.disconnect();
      colors.disconnect();
      host.removeEventListener("pointermove", move);
      host.removeEventListener("pointerleave", leave);
      document.removeEventListener("visibilitychange", refresh);
      reduced.removeEventListener("change", refresh);
      theme.removeEventListener("change", paletteChanged);
      window.removeEventListener("resize", refresh);
      canvas.removeEventListener("webglcontextlost", lost);
      canvas.removeEventListener("webglcontextrestored", restored);
      renderer?.dispose();
    },
  };
}

export const uniforms = ["u_res", "u_time", "u_mouse", "u_accent", "u_dark", "u_intensity"];

export const emberShader = /* glsl */ `#version 300 es
precision highp float;
uniform vec2 u_res;
uniform float u_time;
uniform vec2 u_mouse;
uniform vec3 u_accent;
uniform float u_dark;
uniform float u_intensity;
out vec4 outColor;

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);
  for (int i = 0; i < 5; i++) {
    v += a * noise(p);
    p = m * p;
    a *= 0.5;
  }
  return v;
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  vec2 p = (gl_FragCoord.xy - 0.5 * u_res) / u_res.y;
  float t = u_time * 0.07;
  vec2 m = u_mouse.x < 0.0 ? vec2(0.0) : (u_mouse - 0.5 * u_res) / u_res.y;

  vec2 q = vec2(fbm(p * 1.3 + t), fbm(p * 1.3 + vec2(5.2, 1.3) - t));
  vec2 r = vec2(fbm(p * 1.3 + 2.0 * q + vec2(1.7, 9.2) + t * 1.4 + m * 0.35), fbm(p * 1.3 + 2.0 * q + vec2(8.3, 2.8)));
  float f = fbm(p * 1.3 + 2.4 * r);

  vec3 amber = mix(u_accent, vec3(1.0, 0.78, 0.42), 0.55);
  vec3 col = mix(u_accent, amber, smoothstep(0.4, 1.0, length(q)));
  float glow = smoothstep(0.22, 0.72, f);
  float horizon = 1.0 - smoothstep(0.0, 0.9, length((uv - vec2(0.5, 0.2)) * vec2(0.85, 1.9)));
  float alpha = glow * horizon * mix(0.55, 0.8, u_dark);
  alpha += (hash(gl_FragCoord.xy + fract(u_time * 7.0) * 91.0) - 0.5) * 0.05 * horizon;
  alpha = clamp(alpha * u_intensity, 0.0, 1.0);
  outColor = vec4(col * alpha, alpha);
}
`;
